import React, { useState } from 'react';

const LLMChatSidebar = ({ isOpen, onToggle }) => {
  const [messages, setMessages] = useState([]);
  const [inputText, setInputText] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState(null);

  const API_BASE_URL = 'http://localhost:8000';

  const handleSendMessage = async () => {
    if (!inputText.trim()) {
      setError('Please enter a message');
      return;
    }

    setIsLoading(true);
    setError(null);

    try {
      // Add user message to chat
      const userMessage = { role: 'user', content: inputText };
      setMessages([...messages, userMessage]);
      setInputText('');

      // Send to backend
      const response = await fetch(`${API_BASE_URL}/api/chat`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          message: inputText,
          context: 'You are a helpful assistant about Puerto Rican culture, cuisine, language, and traditions. Provide informative and engaging responses.',
        }),
      });

      if (!response.ok) {
        const errorData = await response.json();
        throw new Error(errorData.detail || 'Chat failed');
      }

      const data = await response.json();
      const assistantMessage = { role: 'assistant', content: data.response };
      setMessages((prev) => [...prev, assistantMessage]);
    } catch (err) {
      console.error('Chat error:', err);
      setError(
        err && err.message
          ? err.message
          : 'Failed to connect to LLM. Make sure LM Studio is running on port 1234.'
      );
      // Remove the user message if there was an error
      setMessages((prev) => prev.slice(0, -1));
    } finally {
      setIsLoading(false);
    }
  };

  const handleClear = () => {
    setMessages([]);
    setInputText('');
    setError(null);
  };

  return (
    <>
      {/* Toggle Button */}
      <button
        className={`translation-toggle ${isOpen ? 'open' : ''}`}
        onClick={onToggle}
        title="Toggle LLM Chat"
        style={{
          position: 'fixed',
          bottom: '20px',
          right: '20px',
          borderRadius: '50%',
          width: '60px',
          height: '60px',
          zIndex: '1000',
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center',
          border: 'none',
          cursor: 'pointer',
          background: '#6f42c1',
          color: '#fff',
          fontSize: '24px',
          boxShadow: '0 4px 12px rgba(111, 66, 193, 0.4)'
        }}
      >
        <i className="fas fa-robot"></i>
      </button>

    </>
  );
};

export default LLMChatSidebar;
